 Future<void> schedule(Reminder reminder,{bool quietHoursEnabled=false,String quietStart='22:00',String quietEnd='07:00'})async{await initialize();if(!reminder.enabled||reminder.completed)return;final original=reminder.snoozedUntil??reminder.dueAt;if(original.isBefore(DateTime.now()))return;var when=original;var quietAdjusted=false;if(quietHoursEnabled){final startParts=quietStart.split(':').map(int.parse).toList(),endParts=quietEnd.split(':').map(int.parse).toList();final startMinute=startParts[0]*60+startParts[1],endMinute=endParts[0]*60+endParts[1],minute=when.hour*60+when.minute;final overnight=startMinute>endMinute;final inside=overnight?(minute>=startMinute||minute<endMinute):(minute>=startMinute&&minute<endMinute);if(inside&&startMinute!=endMinute){when=DateTime(when.year,when.month,when.day,endParts[0],endParts[1]);if(overnight&&minute>=startMinute)when=when.add(const Duration(days:1));quietAdjusted=true;}}const details=NotificationDetails(android:AndroidNotificationDetails('pawpal_care','Care reminders',channelDescription:'Owner-created pet care reminders',importance:Importance.defaultImportance,priority:Priority.defaultPriority));final components=quietAdjusted||reminder.snoozedUntil!=null?null:switch(reminder.repeat){'daily'=>DateTimeComponents.time,'weekly'=>DateTimeComponents.dayOfWeekAndTime,_=>null};await _plugin.zonedSchedule(_id(reminder.id),reminder.title,'PawPal reminder · ${reminder.category}',tz.TZDateTime.from(when,tz.local),details,androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle,matchDateTimeComponents:components);}
